function validate([n, m, k]) {
  if (!Number.isInteger(k) || k < 2 || k > 100000) return 'k is between 2 and 10^5.';
  if (!Number.isInteger(n) || !Number.isInteger(m) || n < 1 || m < 1 || n > 2 * k || m > 2 * k) return 'n and m are between 1 and 2 * k.';
  if (n > k && m > k) return 'Both logs are longer than k, so three trucks cannot carry them.';
  return null;
}

