function minCuttingCost(n, m, k) {
  // Three trucks hold at most three logs, so at most one cut: try no cut and every single cut of either log.
  let best = n <= k && m <= k ? 0 : Infinity;
  for (const [log, other] of [[n, m], [m, n]]) {
    for (let len1 = 1; len1 < log; len1++) {
      const len2 = log - len1;
      if (len1 <= k && len2 <= k && other <= k) best = Math.min(best, len1 * len2);
    }
  }
  return best;
}

