function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * limit);
  const k = size === 'large' ? 100000 - pick(1000) : 2 + pick(11);
  // Mix edge lengths (1, k, k + 1, 2k) with random ones.
  const length = () => {
    const r = rand();
    if (r < 0.15) return k;
    if (r < 0.3) return 2 * k;
    if (r < 0.4) return k + 1;
    if (r < 0.5) return 1;
    return 1 + pick(2 * k);
  };
  let n = length();
  let m = length();
  // Two logs longer than k would need four trucks, so shorten one of them.
  if (n > k && m > k) {
    if (rand() < 0.5) n = 1 + pick(k);
    else m = 1 + pick(k);
  }
  return [n, m, k];
}
